    scope_node = node_by_title(doc, scope)
    ents = {}
    # Helper to add entity
    def add(name, description):
        if name not in ents:
            ents[name] = description

    # Get machine table
    for cid in children(doc, scope_node):
        child = node_by_id(doc, cid)
        if child['title'].endswith(': Machines'):
            for row_idx, row in table_rows(child):
                machine_id = row.get('machine')
                if machine_id:
                    add(machine_id, f"Machine {machine_id}")
                    # Also add their capacity as part of entity?
                    # We'll add jobs and tasks separately.
        elif child['title'].endswith(': Task log'):
            for row_idx, row in table_rows(child):
                task_id = row.get('task')
                job_id = row.get('job')
                if task_id:
                    add(task_id, f"Task {task_id} (job {job_id})")
                if job_id:
                    add(job_id, f"Job {job_id}")
    return [{'id': k, 'description': v} for k, v in sorted(ents.items())]


