import json
from typing import List, Dict, Any, Union

# --------------- helpers assumed to exist in the runtime ----------------
# node_by_title(doc, title) -> node dict
# node_by_id(doc, node_id) -> node dict
# children(doc, node) -> list of child node ids
# table_rows(node) -> list of (row_index, {col_name: cell_str})

# -------------------------- helper utilities ----------------------------
def _as_int(v: str) -> int:
    try:
        return int(v)
    except Exception:
        return 0


def _as_float(v: str) -> Union[float, None]:
    if v is None or v == "-":
        return None
    try:
        return float(v)
    except Exception:
        return None


def _make_src(node_id, row_idx, cols):
    return [[node_id, row_idx, cols]]


# ----------------------------- 1. Entities --------------------------------
def entities(doc: Dict, scope: str) -> List[Dict[str, str]]:
    """Return a list of distinct entities in the given scope."""
    scope_node = next((n for n in doc["nodes"] if n.get("title") == scope), None)
    if scope_node is None:
        return []

    entity_map: Dict[str, str] = {}

    # Machines
    for cid in children(doc, scope_node):
        child = node_by_id(doc, cid)
        if (
            child.get("kind") == "table"
            and child.get("title", "").endswith(": Machines")
        ):
            for row_index, row in table_rows(child):
                mid = row.get("machine")
                if mid:
                    entity_map[mid] = f"Machine {mid}"

    # Jobs & Tasks
    for cid in children(doc, scope_node):
        child = node_by_id(doc, cid)
        if (
            child.get("kind") == "table"
            and child.get("title", "").endswith(": Task log")
        ):
            for row_index, row in table_rows(child):
                t_id = row.get("task")
                if t_id:
                    entity_map[t_id] = f"Task {t_id}"
                j_id = row.get("job")
                if j_id:
                    entity_map[j_id] = f"Job {j_id}"

    return [{"id": k, "description": v} for k, v in sorted(entity_map.items())]


# ----------------------------- 2. Recorded End ----------------------------
def recorded_end(doc: Dict, scope: str) -> Union[float, None]:
    """Return the last time point covered by the scope's records."""
    scope_node = next((n for n in doc["nodes"] if n.get("title") == scope), None)
    if scope_node is None:
        return None

    last: Union[float, None] = None
    for cid in children(doc, scope_node):
        child = node_by_id(doc, cid)
        if child.get("kind") == "table":
            cols = child.get("table", {}).get("columns", [])
            if "time" not in cols:
                continue
            for row_idx, row in table_rows(child):
                t = _as_float(row.get("time"))
                if t is None:
                    continue
                last = t if last is None or t > last else last
    return last


# ----------------------------- 3. Inputs ---------------------------------
def inputs(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """Return list of input records for the given scope."""
    scope_node = next((n for n in doc["nodes"] if n.get("title") == scope), None)
    if scope_node is None:
        return []

    inps: List[Dict[str, Any]] = []

    # Machines
    for cid in children(doc, scope_node):
        child = node_by_id(doc, cid)
        if (
            child.get("kind") == "table"
            and child.get("title", "").endswith(": Machines")
        ):
            node_id = cid
            for row_idx, row in table_rows(child):
                mid = row.get("machine")
                if not mid:
                    continue
                cpu = _as_int(row.get("CPU"))
                mem = _as_int(row.get("memory"))
                fail_time = _as_float(row.get("fails at"))
                return_time = _as_float(row.get("returns at"))

                # Initial machine state
                inps.append(
                    {
                        "id": f"machine_{mid}",
                        "time": None,
                        "kind": "machine",
                        "entities": [mid],
                        "fields": {
                            "CPU": cpu,
                            "memory": mem,
                            "fails_at": fail_time,
                            "returns_at": return_time,
                        },
                        "src": _make_src(node_id, row_idx, ["machine", "CPU", "memory", "fails at", "returns at"]),
                    }
                )

                # Failure event
                if fail_time is not None:
                    inps.append(
                        {
                            "id": f"machine_{mid}_fail",
                            "time": fail_time,
                            "kind": "failure",
                            "entities": [mid],
                            "fields": {},
                            "src": _make_src(node_id, row_idx, ["fails at"]),
                        }
                    )

                # Return event
                if return_time is not None:
                    inps.append(
                        {
                            "id": f"machine_{mid}_return",
                            "time": return_time,
                            "kind": "return",
                            "entities": [mid],
                            "fields": {},
                            "src": _make_src(node_id, row_idx, ["returns at"]),
                        }
                    )

    # Task submissions
    for cid in children(doc, scope_node):
        child = node_by_id(doc, cid)
        if (
            child.get("kind") == "table"
            and child.get("title", "").endswith(": Task log")
        ):
            node_id = cid
            for row_idx, row in table_rows(child):
                if row.get("event") != "submit":
                    continue
                t_id = row.get("task")
                j_id = row.get("job")
                sub_time = _as_float(row.get("time"))
                priority = _as_int(row.get("priority"))
                cpu = _as_int(row.get("CPU"))
                mem = _as_int(row.get("memory"))
                run = _as_int(row.get("run time"))

                inps.append(
                    {
                        "id": f"submit_{t_id}",
                        "time": sub_time,
                        "kind": "submission",
                        "entities": [t_id],
                        "fields": {
                            "job": j_id,
                            "priority": priority,
                            "CPU": cpu,
                            "memory": mem,
                            "run_time": run,
                        },
                        "src": _make_src(
                            node_id,
                            row_idx,
                            ["time", "task", "job", "priority", "CPU", "memory", "run time"],
                        ),
                    }
                )

    # Order the inputs deterministically: time None first, then numeric times, then id
    inps.sort(key=lambda x: (
        x["time"] is not None,
        x["time"] if x["time"] is not None else -1,
        x["id"],
    ))
    return inps


# ----------------------------- 4. Outcomes --------------------------------
def outcomes(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """Return list of outcome records for the given scope."""
    scope_node = next((n for n in doc["nodes"] if n.get("title") == scope), None)
    if scope_node is None:
        return []

    outs: List[Dict[str, Any]] = []

    for cid in children(doc, scope_node):
        child = node_by_id(doc, cid)
        if (
            child.get("kind") == "table"
            and child.get("title", "").endswith(": Task log")
        ):
            node_id = cid
            for row_idx, row in table_rows(child):
                ev = row.get("event")
                if ev == "submit":
                    continue  # submission is an input
                t_id = row.get("task")
                t_time = _as_float(row.get("time"))
                machine_id = row.get("machine")
                entities: List[str] = [t_id]
                if machine_id and machine_id != "-":
                    entities.append(machine_id)

                # Build outcome record
                outs.append(
                    {
                        "time": t_time,
                        "kind": ev,
                        "entities": entities,
                        "value": None,
                        "src": _make_src(
                            node_id, row_idx, ["time", "task"] + (["machine"] if machine_id and machine_id != "-" else [])
                        ),
                    }
                )

    # Order deterministically
    outs.sort(key=lambda x: (
        x["time"] if x["time"] is not None else -1,
        x["kind"],
        tuple(x["entities"]),
    ))
    return outs


# ----------------------------- 5. Parameters --------------------------------
def params(doc: Dict, scope: str) -> Dict[str, float]:
    """Return parameter constants for the given scope."""
    # No explicit constants are declared in this document
    return {}
